CREATE TABLE IF NOT EXISTS br_requests(id TEXT PRIMARY KEY,business_id TEXT REFERENCES portfolio_businesses(id),entry_key TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,payload TEXT NOT NULL,snapshot TEXT NOT NULL,preview TEXT NOT NULL,status TEXT NOT NULL,created_by TEXT NOT NULL,approved_by TEXT,approved_at TEXT,applied_by TEXT,result_business TEXT REFERENCES portfolio_businesses(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS br_assignment_controls(business_id TEXT NOT NULL,agent TEXT NOT NULL,PRIMARY KEY(business_id,agent),FOREIGN KEY(business_id,agent) REFERENCES bf_ai_assignments(business_id,agent));
CREATE TABLE IF NOT EXISTS br_events(id INTEGER PRIMARY KEY,request_id TEXT REFERENCES br_requests(id),business_id TEXT REFERENCES portfolio_businesses(id),actor TEXT NOT NULL,event TEXT NOT NULL,created_at TEXT NOT NULL);
